const assertUuid = (value, field) => {
  const text = String(value ?? '').trim();
  if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(text)) {
    throw new Error(`Invalid ${field}: ${value}`);
  }
  return text;
};

const item = $input.first();
const body = item.json.body ?? item.json ?? {};

const userId = assertUuid(body.user_id, 'user_id');

// El archivo llega en la propiedad binaria `data` (el front hace
// formData.append('data', file), igual que el logo de clínica).
const binary = item.binary?.data;
if (!binary) throw new Error('signature file is required (binary property "data")');

const allowed = ['image/png', 'image/jpeg', 'image/webp'];
if (!allowed.includes(binary.mimeType)) {
  throw new Error(`Unsupported signature type: ${binary.mimeType}`);
}

// 1 MB, el mismo límite que valida el front.
if (binary.fileSize && Number(String(binary.fileSize).replace(/[^0-9]/g, '')) > 1024 * 1024) {
  throw new Error('Signature file exceeds 1 MB');
}

return [{
  json: {
    user_id: userId,
    filename: binary.fileName || `signature-${userId}.png`,
    mimetype: binary.mimeType,
  },
  binary: item.binary,
}];

// El borrado del archivo anterior es best-effort: si falla, la firma nueva ya
// quedó guardada y no hay razón para devolver un error al usuario.
const saved = $('Guardar en users').first().json;

if (!saved || saved.error || !saved.id) {
  return [{ json: { statusCode: 500, body: { message: 'No se pudo guardar la firma.' } } }];
}

return [{ json: { statusCode: 200, body: {
  success: true,
  user_id: saved.id,
  filename: saved.signature_filename,
  mimetype: saved.signature_mimetype,
  updated_at: saved.signature_updated_at,
} } }];
